@startuml

class InsurancePolicy {
  + PolicyId : int
  + Type : string
}

class Customer {
  + CustId : int
  + Name : string
}

class Contract {
  + ContractId : int
  + PolicyId : int
  + CustId : int
  + EffectiveDate : date
  + ExpiryDate : date
}

InsurancePolicy "1" -- "*" Contract
Customer "0..*" -- "*" Contract

@enduml

